inputs = ['wi', 'wbui', 'wkey', 'jwgg', 'gvjcvk']
outputs = ['dxaai', 'dxaabui', 'dxaakadxai', 'jdxaagg', 'gvjdxabgvk']

print("Character-by-character analysis:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"\n{inp} -> {outp}")
    print("  Position: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            print(f"{j}({inp[j]}->{outp[j]}) ", end="")
        elif j < len(inp):
            print(f"{j}({inp[j]}->) ", end="")
        else:
            print(f"{j}(->{outp[j]}) ", end="")
    print()

